// ============================================================
// Racing lines (BUILD 107). Pre-computed offline (outputs/harness/lineopt/mincurv.py):
// a GLOBAL minimum-curvature line over the whole lap on each circuit, using the
// full track width (car centre 0.6 m inside the white line, so the outside
// wheels use the kerbs), with a hard cap so no corner is tighter than the car
// can physically turn (steerLockAt in physics.js). Validated against TUM's
// published F1 racelines (mean correlation ~0.9 over 15 circuits) and real
// 2025 pole laps (OpenF1 position data).
// Each entry: lateral offset from the centreline every `step` TrackData
// samples, Int16 (little-endian) in 1 cm units, base64. + = TrackData normal direction.
// ============================================================
const RACELINES = {
  abudhabi: { n: 3433, step: 2, d: "" },
  australia: { n: 3293, step: 2, d: "" },
  austria: { n: 2687, step: 2, d: "" },
  azerbaijan: { n: 3687, step: 2, d: "" },
  bahrain: { n: 3363, step: 2, d: "" },
  belgium: { n: 4200, step: 2, d: "" },
  brazil: { n: 2678, step: 2, d: "" },
  britain: { n: 3666, step: 2, d: "" },
  canada: { n: 2708, step: 2, d: "" },
  china: { n: 3380, step: 2, d: "" },
  hungary: { n: 2722, step: 2, d: "" },
  italy: { n: 3610, step: 2, d: "" },
  japan: { n: 3614, step: 2, d: "" },
  madrid: { n: 3351, step: 2, d: "" },
  mexico: { n: 2665, step: 2, d: "" },
  miami: { n: 3357, step: 2, d: "" },
  monaco: { n: 2046, step: 2, d: "" },
  netherlands: { n: 2685, step: 2, d: "" },
  qatar: { n: 3366, step: 2, d: "" },
  saudi: { n: 3837, step: 2, d: "" },
  singapore: { n: 3051, step: 2, d: "" },
  spain: { n: 2890, step: 2, d: "" },
  usa: { n: 3419, step: 2, d: "" },
  vegas: { n: 3860, step: 2, d: "" }
};
// tiny base64 decoder (no atob/Buffer needed — works in any JS context)
function _rlB64(s) {
  const A = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
  let out = "", buf = 0, bits = 0;
  for (let i = 0; i < s.length; i++) {
    const c = A.indexOf(s[i]); if (c < 0) continue;
    buf = (buf << 6) | c; bits += 6;
    if (bits >= 8) { bits -= 8; out += String.fromCharCode((buf >> bits) & 255); }
  }
  return out;
}
function racelineFor(track) {
  const e = RACELINES[track.def && track.def.id];
  if (!e || e.n !== track.n) return null;
  const bin = _rlB64(e.d);
  const m = bin.length >> 1, q = new Float32Array(m);
  for (let i = 0; i < m; i++) { let b = bin.charCodeAt(2 * i) | (bin.charCodeAt(2 * i + 1) << 8); if (b > 32767) b -= 65536; q[i] = b * 0.01; }
  const N = track.n, out = new Float32Array(N);
  for (let i = 0; i < N; i++) {
    // Catmull-Rom between the stored points: smooth, no curvature kinks
    const x = i / e.step, i1 = Math.floor(x) % m, f = x - Math.floor(x);
    const p0 = q[(i1 - 1 + m) % m], p1 = q[i1], p2 = q[(i1 + 1) % m], p3 = q[(i1 + 2) % m];
    out[i] = 0.5 * (2 * p1 + (-p0 + p2) * f + (2 * p0 - 5 * p1 + 4 * p2 - p3) * f * f + (-p0 + 3 * p1 - 3 * p2 + p3) * f * f * f);
  }
  return out;
}
